CREATE TABLE `return_requests` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `order_id` integer NOT NULL, `reason` text NOT NULL, `status` text DEFAULT 'requested' NOT NULL, `requested_by` text DEFAULT '' NOT NULL, `decided_by` text, `decided_at` integer, `created_at` integer NOT NULL, FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON UPDATE no action ON DELETE no action);
